pts = [(1,3),(1,5),(1,6),(1,7),(1,12),(2,12),(3,10),(4,3),(4,10),(5,10),(6,3),(6,10),(7,3),(8,10),(10,10),(11,3),(12,3),(13,10),(14,10),(15,3),(15,10),(16,3),(16,10),(17,3),(17,10),(17,12),(18,3),(19,3),(20,3),(20,5),(20,8),(20,9)]
h,w=21,15
G=[[1]*w for _ in range(h)]
for r,c in pts:G[r][c]=9
O=[row[:] for row in G]
# complete gaps between 9s on each row/column
for r in range(h):
    cs=[c for c in range(w) if G[r][c]==9]
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b):
            if O[r][c]==1: O[r][c]=2
for c in range(w):
    rs=[r for r in range(h) if G[r][c]==9]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if O[r][c]==1: O[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in O))

O2=[row[:] for row in G]
# complete the three marked vertical strokes between their extreme points
for c in [3,10,12]:
    rs=[r for r in range(h) if G[r][c]==9]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if O2[r][c]==1: O2[r][c]=2
# complete the outer rectangle boundary over the global bounding box
minr,maxr=min(r for r,c in pts),max(r for r,c in pts)
minc,maxc=min(c for r,c in pts),max(c for r,c in pts)
for c in range(minc,maxc+1):
    for r in [minr,maxr]:
        if O2[r][c]==1: O2[r][c]=2
for r in range(minr,maxr+1):
    for c in [minc,maxc]:
        if O2[r][c]==1: O2[r][c]=2
print(minr,maxr,minc,maxc)
print('\n'.join(' '.join(map(str,row)) for row in O2))

D=[row[:] for row in G]
# main rectangle from row 1 through row 17, cols 3..12
for c in range(3,13):
    for r in (1,17):
        if D[r][c]==1:D[r][c]=2
for r in range(1,18):
    for c in (3,12):
        if D[r][c]==1:D[r][c]=2
# repeatedly marked internal vertical line and left tail
for c in (3,10):
    rs=[r for r in range(h) if G[r][c]==9]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b):
            if D[r][c]==1:D[r][c]=2
# bottom horizontal marked fragment
for c in range(3,10):
    if D[20][c]==1:D[20][c]=2
print('\n'.join(' '.join(map(str,row)) for row in D))
